import{_ as t,o as d,c as o,ag as a}from"./chunks/framework.DO6ntPSX.js";const p=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1785115728000}'),i={name:"guide/configuration.md"};function n(r,e,c,l,s,u){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>Copy <code>.env.example</code> as the starting point. The main settings are:</p><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>API_KEY</code></td><td>—</td><td>OpenAI-compatible API key</td></tr><tr><td><code>BASE_URL</code></td><td><code>https://api.openai.com/v1</code></td><td>LLM endpoint; remote endpoints must use HTTPS</td></tr><tr><td><code>LLM_MODEL</code></td><td><code>deepseek-chat</code></td><td>Chat and query-decomposition model</td></tr><tr><td><code>LLM_TEMPERATURE</code></td><td><code>0.2</code></td><td>Generation temperature</td></tr><tr><td><code>LLM_TOP_K_MIN</code></td><td><code>12</code></td><td>Minimum retrieved chunks for standard retrieval</td></tr><tr><td><code>LLM_TOP_K_MAX</code></td><td><code>70</code></td><td>Maximum retrieved chunks for standard retrieval</td></tr><tr><td><code>ALPHA</code></td><td><code>0.7</code></td><td>Graph RAG semantic/graph fusion weight</td></tr><tr><td><code>RAG_WATCH_DIR</code></td><td>—</td><td>Directory watched by the TUI</td></tr><tr><td><code>EMBEDDING_MODEL_PATH</code></td><td>—</td><td>Local embedding model path; takes precedence</td></tr><tr><td><code>EMBEDDING_MODEL_NAME</code></td><td><code>all-MiniLM-L6-v2</code></td><td>Embedding model ID used for local/ModelScope loading</td></tr><tr><td><code>MNEME_DOCUMENT_ROOT</code></td><td>—</td><td>Optional root directory allowed for indexed files</td></tr><tr><td><code>MNEME_MAX_DOCUMENT_BYTES</code></td><td><code>52428800</code></td><td>Maximum document size, 50 MiB</td></tr><tr><td><code>MNEME_MAX_PDF_PAGES</code></td><td><code>2000</code></td><td>Maximum pages accepted from one PDF</td></tr><tr><td><code>MNEME_MAX_REMOTE_CONTEXT_CHARS</code></td><td><code>60000</code></td><td>Maximum retrieved context sent to an LLM endpoint</td></tr><tr><td><code>MNEME_ALLOW_INSECURE_HTTP</code></td><td>unset</td><td>Explicitly allow non-local HTTP endpoints; use only for controlled development</td></tr></tbody></table><h2 id="embedding-model-loading" tabindex="-1">Embedding Model Loading <a class="header-anchor" href="#embedding-model-loading" aria-label="Permalink to &quot;Embedding Model Loading&quot;">​</a></h2><p>Embedding models are first loaded from the configured local path or cache. If unavailable, Mneme uses the configured model identifier for ModelScope fallback; the default is <code>all-MiniLM-L6-v2</code>.</p><h2 id="endpoint-safety" tabindex="-1">Endpoint Safety <a class="header-anchor" href="#endpoint-safety" aria-label="Permalink to &quot;Endpoint Safety&quot;">​</a></h2><p>For non-local endpoints, HTTPS is required by default. Plain HTTP is allowed for loopback addresses such as <code>localhost</code>, <code>127.0.0.1</code>, and <code>::1</code>. A non-local HTTP endpoint requires the explicit <code>MNEME_ALLOW_INSECURE_HTTP=1</code> override.</p><h2 id="document-safeguards" tabindex="-1">Document Safeguards <a class="header-anchor" href="#document-safeguards" aria-label="Permalink to &quot;Document Safeguards&quot;">​</a></h2><ul><li>Document size, PDF page count, and an optional allowed document root can be limited</li><li><code>.env</code> is explicitly rejected as an indexable document</li><li>Retrieved text is placed inside explicit untrusted-document boundaries for prompt-injection resistance</li></ul>',9)])])}const _=t(i,[["render",n]]);export{p as __pageData,_ as default};
